export const Default = (args) => (
  <CheckboxGroup {...args} readOnly={args.readOnly || undefined}>
    <Checkbox labelText="Checkbox label" id="checkbox-label-1" />
    <Checkbox labelText="Checkbox label" id="checkbox-label-2" />
  </CheckboxGroup>
);

Default.args = {
  ...groupArgs,
};

Default.argTypes = { ...groupArgTypes };

Default.parameters = {
  controls: {
    include: groupControls,
  },
};

export const Horizontal = (args) => {
  return (
    <CheckboxGroup {...args} readOnly={args.readOnly || undefined}>
      <Checkbox labelText="Checkbox label" id="checkbox-label-1" />
      <Checkbox labelText="Checkbox label" id="checkbox-label-2" />
      <Checkbox labelText="Checkbox label" id="checkbox-label-3" />
    </CheckboxGroup>
  );
};

Horizontal.args = {
  ...groupArgs,
  orientation: 'horizontal',
};

Horizontal.argTypes = {
  ...groupArgTypes,
  orientation: {
    ...groupArgTypes.orientation,
    table: {
      readonly: true,
    },
  },
};

Horizontal.parameters = {
  controls: {
    include: groupControls,
  },
};

export const Single = (args) => {
  const [{ checked }, updateArgs] = useArgs();

  return (
    <Checkbox
      {...args}
      checked={checked}
      id="checkbox-single"
      onChange={(event, data) => {
        updateArgs({ checked: data.checked });
        args.onChange?.(event, data);
      }}
    />
  );
};

Single.args = {
  ...checkboxArgs,
};

Single.argTypes = {
  ...checkboxArgTypes,
};

Single.parameters = {
  controls: {
    include: checkboxControls,
  },
};

export const Skeleton = () => <CheckboxSkeleton />;

Skeleton.parameters = {
  controls: {
    disable: true,
  },
};
